SELECT generico5.categoria AS categoria FROM generico5 WHERE ((generico5.anunciante IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) >= 2010) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) <= 2015) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) IN (2014, 2015)) AND (generico5.medio = 'RADIO') AND (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) IN (1, 2, 3, 4, 5))) GROUP BY generico5.categoria;
